"""Add "Share > LinkVault" to the Flutter project generated by `flet build apk`.

Usage (from the repo root):
    cd app && flet build apk            # first build generates app/build/flutter
    python ../native/android/patch_share_intent.py build/flutter
    flet build apk                      # rebuild with the share target

The patch survives later builds. Re-run it if you change [tool.flet] settings in
app/pyproject.toml, because that makes flet regenerate the Flutter project.
"""

import re
import sys
from pathlib import Path

INTENT_FILTER = """            <!-- LinkVault: appear in the Android share sheet -->
            <intent-filter>
                <action android:name="android.intent.action.SEND" />
                <category android:name="android.intent.category.DEFAULT" />
                <data android:mimeType="text/plain" />
            </intent-filter>
"""


def patch_manifest(flutter_dir: Path) -> None:
    manifest = flutter_dir / "android/app/src/main/AndroidManifest.xml"
    text = manifest.read_text(encoding="utf-8")
    if "android.intent.action.SEND" in text:
        print("manifest: already patched")
        return
    # Insert right before the closing tag of the main activity.
    m = re.search(r"<activity[^>]*android:name=\"\.MainActivity\".*?</activity>", text, re.S)
    if not m:
        sys.exit("Could not find .MainActivity in AndroidManifest.xml")
    block = m.group(0)
    patched = block.replace("</activity>", INTENT_FILTER + "        </activity>")
    manifest.write_text(text.replace(block, patched), encoding="utf-8")
    print(f"manifest: added SEND intent-filter ({manifest})")


def patch_activity(flutter_dir: Path) -> None:
    candidates = list((flutter_dir / "android/app/src/main").rglob("MainActivity.kt"))
    if not candidates:
        sys.exit("Could not find MainActivity.kt")
    target = candidates[0]
    package = re.search(r"^package\s+([\w.]+)", target.read_text(encoding="utf-8"), re.M).group(1)
    template = (Path(__file__).parent / "MainActivity.kt").read_text(encoding="utf-8")
    target.write_text(template.replace("__PACKAGE__", package), encoding="utf-8")
    print(f"activity: replaced {target} (package {package})")


if __name__ == "__main__":
    root = Path(sys.argv[1] if len(sys.argv) > 1 else "build/flutter")
    if not (root / "android").is_dir():
        sys.exit(f"{root} is not a Flutter project. Run `flet build apk` first.")
    patch_manifest(root)
    patch_activity(root)
